		if (((x - ibeg->first) * (x - ibeg->first)) + ((y - ibeg->second) * (y - ibeg->second)) < 400) {
			//找到了，删除该顶点
			Vertex.erase(ibeg);
			break;
		}
		ibeg++;
	}
}
