        A.mat[1][1]=1;
        A.mat[1][2]=1;
        A.mat[2][1]=1;
        MyMat x(2,1);
        x.mat[1][1]=1;
        x.mat[2][1]=1;
        auto ans = quickpow(x,A,n);
        cout<<ans.mat[1][1]<<endl;
    }
    return 0;
}
