using System.IO;
public class RecordData : MonoBehaviour
{
    #region 单例
    public static RecordData instance;
    private void Awake()
    {
        if (instance == null)
        {
            DontDestroyOnLoad(gameObject);
            instance = this;
            // 创建全空数组
            for (int i = 0; i < recordNum; i++)
            {
                recordName[i] = "";
            }
            Load();
        }
        else if (instance != this)
        {
            Destroy(gameObject);
        }
